<?php require '../config/database.php';require '../config/auth.php';require_role('student');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO queries(student_id,subject,message) VALUES(?,?,?)');$q->execute([$_SESSION['student_id'],trim($_POST['subject']),trim($_POST['message'])]);$msg='Query sent successfully.';}$q=$pdo->prepare('SELECT * FROM queries WHERE student_id=? ORDER BY id DESC');$q->execute([$_SESSION['student_id']]);$rows=$q->fetchAll();$page_title='Helpdesk';require '../includes/header.php';?><h1>Student Helpdesk</h1><p class="muted">Send a query to administration.</p><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="card"><form method="post"><div class="form"><label>Subject</label><input name="subject" required></div><div class="form"><label>Query</label><textarea name="message" rows="5" required></textarea></div><button class="btn">Send Query</button></form></div><div class="card" style="margin-top:15px"><div class="title">My Queries</div><table><tr><th>Subject</th><th>Message</th><th>Reply</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['subject'])?></td><td><?=htmlspecialchars($r['message'])?></td><td><?=htmlspecialchars($r['reply']?:'Pending')?></td></tr><?php endforeach;?></table></div><?php require '../includes/footer.php';?>
